import { item as q, d, s, e } from '../equilibri/proposal.js';

export const mythSecondExpansionDrafts = [
  cultural({code:'S151',id:'atena-i-lolivera',title:'Atena i l’olivera',grade:'5',level:'middle',universeIds:['mites-antiguitat'],voice:'Callirrhoe',music:'M2',batch:'T-C',
    introduction:'Comprensió oral. Atena i l’olivera. Un mite grec sobre la ciutat d’Atenes.',
    summary:'Dos déus volen protegir la mateixa ciutat. Cadascun hi deixa un senyal davant del rei.',
    context:'En aquest mite grec, dos déus arriben al turó d’una ciutat antiga. Fixa’t en què hi fa cadascun i en quin paper hi té el rei que observa l’escena.',
    editorialFocus:'5è intermèdia: comparació de dos senyals, testimoni i decisió. Sis preguntes duals. S’identifica el trident i s’introdueix el paper dels jutges sense exigir coneixements previs. No barrejar les versions del cavall, la votació popular o l’aigua dolça.',
    factualSources:[{label:'Apol·lodor, Biblioteca 3.14.1, edició i traducció de J. G. Frazer (1921), Perseus Digital Library. Text i notes sobre l’aigua marina, l’olivera, el rei testimoni i el judici dels déus.',url:'https://beta.perseus.tufts.edu/urn%3Acts%3AgreekLit%3Atlg0548.tlg001.perseus-eng2/section%3A3.14.1/'}],
    illustrationBrief:'Turó rocós damunt d’una ciutat grega antiga amb dos visitants observats pel rei. Sense font, olivera, trident en acció, noms, vencedor o fruit que avanci els dos senyals.',
    transcript:[d('Adaptació pròpia del nucli d’Apol·lodor 3.14.1: senyal d’aigua marina, olivera, rei com a testimoni i déus jutges. Les rèpliques, els gestos i l’explicació quotidiana de l’arbre són recreacions. Es resumeixen els dotze jutges i s’omet la inundació posterior; no es converteix en concurs votat pels habitants. Base M2.'),
      s('disputa','Narrador','Abans que la ciutat d’Atenes dugués aquest nom, diu el mite que dos déus en volien ser els protectors. Atena, deessa de la saviesa i dels oficis, reclamava aquell lloc. Posidó, el déu del mar, també el volia. Cadascun es disposava a deixar-hi un senyal que mostrés la seva presència.'),
      s('roca','Narrador','Posidó va pujar a la part alta de la ciutat. Duia un trident, una mena de forca amb tres puntes. Va alçar-lo i va colpejar la roca. Del lloc on havia donat el cop en va brollar aigua. El rei, que observava l’escena, s’hi va acostar. Aquella aigua tenia el gust salat del mar.'),
      s('arbre','Narrador','Després hi va arribar Atena. Va demanar al rei que es quedés a mirar què faria. La deessa va plantar una olivera en aquell turó rocós. El rei va veure com l’arbre arrelava i s’hi estenia. Les fulles estretes es movien a l’aire i deixaven veure una cara més clara quan giraven.'),
      s('regal','Narrador','Atena va acostar la mà a una branca. Va explicar que aquell arbre donaria olives. Amb les olives es podia fer oli per preparar menjar i per encendre llànties, els petits recipients amb una metxa que servien per il·luminar les cases. El rei es va quedar al costat de l’arbre que acabava de veure plantar.'),
      s('jutges','Narrador','Però la disputa continuava. Posidó assenyalava l’aigua que havia fet sortir de la roca. Atena assenyalava la seva olivera. Altres déus es van reunir per decidir a qui correspondria protegir la ciutat. Van escoltar el rei. Ell va explicar el que havia presenciat: havia vist Atena plantar l’arbre en aquell lloc.'),
      s('decisio','Narrador','Els jutges van concedir la ciutat a Atena. En aquesta versió del mite, el rei havia fet de testimoni de l’acció de la deessa. L’olivera es va convertir en un dels seus senyals. El relat relaciona el nom d’Atenes amb Atena i situa al mateix turó les dues marques de la disputa: l’aigua salada de Posidó i l’arbre de la deessa. La narració acaba amb la decisió dels déus i l’olivera arrelada damunt de la roca.'),
      d('Un sol timbre narratiu. No afegir onades ni so d’una font com a resposta acústica. El tancament delimita l’episodi adaptat, sense declarar aquesta explicació llegendària un fet històric.')],
    items:[
      q('disputa','Què es disputen Atena i Posidó?','La protecció de la mateixa ciutat.',['Qui pot governar tots els altres déus.','Qui ha de custodiar el trident del rei.','La protecció de la mateixa ciutat.','La propietat de totes les oliveres del món.'],'c','La disputa és local i se situa abans del nom d’Atenes.',[e('disputa','dos déus en volien ser els protectors')]),
      q('aigua','Quin senyal deixa Posidó i com és?','Fa brollar de la roca aigua salada com la del mar.',['Fa sortir de la roca aigua dolça per beure.','Fa brollar de la roca aigua salada del mar.','Planta un arbre que dona olives a la riba.','Encén una llàntia amb l’oli de les olives.'],'b','El relat identifica el gust salat després del cop del trident.',[e('roca','en va brollar aigua'),e('roca','tenia el gust salat del mar')]),
      q('oli','Quins dos usos de l’oli explica Atena?','Preparar menjar i encendre llànties per il·luminar les cases.',['Conservar aliments i preparar perfums.','Preparar menjar i protegir les eines.','Preparar ungüents i encendre llànties.','Preparar menjar i encendre llànties a les cases.'],'d','La narració introdueix què és una llàntia abans de preguntar pels usos. Altres usos possibles de l’oli no són els dos que explica Atena.',[e('regal','oli per preparar menjar i per encendre llànties')],2),
      q('testimoni','Per què els jutges escolten el rei?','Perquè ha presenciat què ha fet Atena i pot explicar-ho.',['Perquè ha presenciat l’acció d’Atena.','Perquè és qui ha plantat l’olivera amb les seves mans.','Perquè els ha ordenat quin déu ha de guanyar.','Perquè ha fet brollar l’aigua abans que Posidó.'],'a','La funció del rei és donar testimoni, no actuar com a únic jutge.',[e('jutges','Ell va explicar el que havia presenciat: havia vist Atena plantar l’arbre')],2),
      q('resolucio','Qui decideix finalment a qui correspon protegir la ciutat?','Els déus reunits com a jutges.',['Els habitants amb una votació a la plaça.','El rei després de provar l’aigua del mar.','Els déus reunits per prendre la decisió.','Posidó després de veure com creix l’arbre.'],'c','El relat diferencia el testimoni del rei i la decisió dels jutges.',[e('jutges','Altres déus es van reunir per decidir'),e('decisio','Els jutges van concedir la ciutat a Atena')]),
      q('marques','Quines dues marques queden relacionades amb la disputa?','L’aigua salada de Posidó i l’olivera d’Atena.',['L’olivera de Posidó i la llàntia del rei.','L’aigua salada de Posidó i l’olivera d’Atena.','El trident d’Atena i el nom que tria el rei.','L’aigua dolça del rei i l’olivera de Posidó.'],'b','Cal conservar la correspondència entre cada déu i el seu senyal.',[e('decisio','l’aigua salada de Posidó i l’arbre de la deessa')],2)
    ]}),
  cultural({code:'S152',id:'aracne-i-el-tapis',title:'Aracne i el tapís',grade:'6',level:'middle',universeIds:['mites-antiguitat'],voice:'Leda',music:'M3',batch:'T-B',
    introduction:'Comprensió oral. Aracne i el tapís. Una adaptació d’un mite de les Metamorfosis d’Ovidi.',
    summary:'Una teixidora molt hàbil rep una visita mentre treballa. La conversa acaba convertida en una competició.',
    context:'En aquest mite, una jove teixidora anomenada Aracne rep una visita al taller mentre treballa. Escolta com comença la conversa, què passa després i com evoluciona l’enfrontament.',
    editorialFocus:'6è intermèdia: identitat amagada, dues representacions artístiques i diferència entre qualitat d’una obra i reacció de qui la contempla. Sis preguntes duals. No identificar bellesa amb justícia ni presentar el càstig com a merescut. Adaptació sensible, sense autolesió ni agressió física detallada.',
    factualSources:[{label:'Ovidi, Metamorfosis VI, 1–145, Pallas et Arachné. Traducció històrica de G. T. Villenave (1806), Bibliotheca Classica Selecta, UCLouvain. Contrast de visita disfressada, dos tapissos, perfecció de l’obra, estrip i transformació.',url:'https://bcs.fltr.ucl.ac.be/meta/06.htm'}],
    illustrationBrief:'Taller antic amb una jove davant d’un teler i una visitant a la porta. Mostrar fils de colors sense escenes figuratives al tapís, cap aranya, gest de trencar o indici de la identitat amagada.',
    transcript:[d('Adaptació catalana pròpia i abreujada d’Ovidi VI, 1–145. Es conserva el nom romà Minerva de la font i no s’alterna amb Atena. S’ometen les representacions sexuals, l’agressió i l’autolesió; la transformació s’enllaça directament amb la destrucció del tapís. No hi ha votació ni vencedor declarat. Les rèpliques són recreació. Base M3.'),
      s('teixidora','Narrador','Aracne era una jove que teixia amb tanta habilitat que la gent s’aturava a mirar-la treballar. Posava fils de colors al teler, l’aparell de fusta on es va formant la tela. Entrellaçant-los, hi feia aparèixer figures i escenes. Molts deien que devia haver après de Minerva, la deessa dels oficis. Aracne insistia que aquella feina era seva i que podia competir amb la mateixa deessa.'),
      s('visita','Narrador','Un dia se li va acostar una dona gran que caminava recolzada en un bastó. Li va aconsellar que reconegués l’habilitat de Minerva. Aracne va deixar els fils un moment. «Si vol comparar la seva feina amb la meva, que vingui», va respondre. La visitant va canviar d’aspecte davant seu. Era Minerva, que havia vingut disfressada.'),
      s('concurs','Narrador','Totes dues es van asseure davant de dos telers. Van triar els fils i van començar a treballar. Hi havia colors molt semblants, amb diferències tan petites que les ombres de les figures semblaven reals. Cada teixidora va construir una escena diferent. La gent mirava com els dibuixos anaven sortint de l’encreuament dels fils.'),
      s('imatges','Narrador','Minerva va representar els déus en un lloc d’honor. També hi va posar escenes en què castigaven persones que els havien desafiat. Aracne, en canvi, va teixir històries d’enganys comesos pels déus. Les figures del seu tapís estaven tan ben fetes que Minerva no hi va trobar cap defecte de treball.'),
      s('reaccio','Narrador','La deessa es va enfurismar en veure què havia representat Aracne. Va agafar la tela de la jove i la va estripar. Els fils que havien format les escenes van quedar esquinçats. Després va transformar la teixidora en una aranya. El cos d’Aracne es va fer petit i les seves extremitats es van convertir en potes fines.'),
      s('teranyina','Narrador','Convertida en aranya, Aracne va començar a deixar anar un fil molt prim. El va subjectar i en va estendre d’altres fins a formar una teranyina. El mite acaba amb aquesta transformació: la jove que havia treballat amb fils al teler ara els produïa amb el seu cos i els teixia suspesa a l’aire. El tapís havia quedat destruït, però la figura d’Aracne continuava unida a l’acció de teixir.'),
      d('Narració continguda, sense veu sinistra, crits ni sons de transformació. El conflicte s’explica sense validar el càstig. No afegir una moral sobre la vanitat o sobre haver d’obeir qui té poder.')],
    items:[
      q('habilitat','Per què la gent s’atura a mirar Aracne?','Per l’habilitat amb què forma figures i escenes teixint.',['Perquè explica als visitants les normes del concurs.','Perquè el seu teler funciona sense tocar els fils.','Per l’habilitat amb què teixeix figures i escenes.','Perquè reparteix roba feta per la deessa Minerva.'],'c','El relat presenta la destresa de la jove abans del conflicte.',[e('teixidora','teixia amb tanta habilitat que la gent s’aturava a mirar-la treballar')]),
      q('disfressa','Qui és la dona gran que parla amb Aracne?','Minerva, que ha vingut disfressada.',['Una altra teixidora que demana aprendre l’ofici.','Minerva, que ha vingut disfressada.','Una clienta que li porta fils per al tapís.','Una jutgessa encarregada de comparar els telers.'],'b','La identitat amagada es revela després de la resposta d’Aracne.',[e('visita','Era Minerva, que havia vingut disfressada')]),
      q('comparacio','Quina diferència principal hi ha entre les escenes dels dos tapissos?','Minerva destaca l’autoritat dels déus; Aracne en representa els enganys.',['Minerva hi posa persones treballant; Aracne, només animals.','Totes dues hi posen els mateixos enganys amb colors diferents.','Aracne hi posa càstigs divins; Minerva, els enganys dels humans.','Minerva hi mostra el poder dels déus; Aracne, els seus enganys.'],'d','La diferència és el contingut representat, no la qualitat dels materials.',[e('imatges','els déus en un lloc d’honor'),e('imatges','castigaven persones que els havien desafiat'),e('imatges','històries d’enganys comesos pels déus')],2),
      q('defecte','Què explica el narrador sobre la qualitat del tapís d’Aracne?','Que Minerva no hi troba cap defecte de treball.',['Que Minerva no hi troba cap defecte de treball.','Que les escenes queden inacabades per falta de fil.','Que els colors són bons però les figures no es reconeixen.','Que copia les mateixes figures que ha fet Minerva.'],'a','La perfecció tècnica es distingeix de la reacció al contingut.',[e('imatges','Minerva no hi va trobar cap defecte de treball')]),
      q('enuig','Què desencadena l’enuig de Minerva, segons el relat?','El que Aracne ha representat sobre els déus.',['El fet que els visitants hagin mogut el teler.','La manca d’habilitat amb què Aracne tracta els fils.','El contingut que Aracne ha representat sobre els déus.','El fet que Aracne hagi amagat el tapís sense acabar.'],'c','La reacció segueix la contemplació d’un tapís sense defectes tècnics.',[e('imatges','històries d’enganys comesos pels déus'),e('reaccio','es va enfurismar en veure què havia representat Aracne')],2),
      q('continuitat','Quina activitat uneix Aracne abans i després de la transformació?','Teixir, primer al teler i després fent la teranyina.',['Ensenyar els déus a fabricar les seves eines.','Teixir, al teler primer i fent la teranyina després.','Aconsellar les joves que visiten el seu taller.','Estripar les teles que no li agraden del concurs.'],'b','El final relaciona l’ofici de la jove amb l’acció de l’aranya.',[e('teranyina','la jove que havia treballat amb fils al teler ara els produïa amb el seu cos')],2)
    ]}),
  cultural({code:'S153',id:'la-gerra-de-pandora',title:'La gerra de Pandora',grade:'6',level:'middle',universeIds:['mites-antiguitat'],voice:'Kore',music:'M1',batch:'T-D',
    introduction:'Comprensió oral. La gerra de Pandora. Una adaptació del mite que explica Hesíode.',
    summary:'Zeus prepara una resposta a l’acció de Prometeu. Pandora arriba a la casa d’Epimeteu, on una gerra ocupa el centre del relat.',
    context:'Escoltaràs un mite antic que intenta explicar la presència de les dificultats al món. Fixa’t en la cadena d’accions de Zeus, Prometeu, Epimeteu i Pandora. La gerra del títol és un recipient gran amb tapa.',
    editorialFocus:'6è intermèdia: quatre noms amb papers diferents i cadena causal de tres moments. Sis preguntes duals. Segueix la gerra d’Hesíode, sense inventar una prohibició, un regal nupcial o l’alliberament posterior de l’esperança. El biaix antic de culpar la primera dona no s’adopta com a lliçó ni com a veritat sobre les dones.',
    factualSources:[{label:'Hesíode, Els treballs i els dies, 42–105. Text primari al Center for Hellenic Studies de Harvard, traducció amb termes grecs: regal, avís a Epimeteu, gerra i esperança retinguda.',url:'https://chs.harvard.edu/primary-source/hesiod-works-and-days-sb/'},{label:'Hesíode, Works and Days, 42–105, traducció històrica de H. G. Evelyn-White (1914), Theoi Classical Texts Library. Contrast del foc amagat, la tapa i la manca de veu dels mals.',url:'https://www.theoi.com/Text/HesiodWorksDays.html'}],
    illustrationBrief:'Casa grega antiga amb una gerra de terrissa tancada al centre i una dona que acaba d’arribar a la porta. Sense formes que surtin de la gerra, esperança figurada, text escrit o prohibició dibuixada.',
    transcript:[d('Adaptació pròpia d’Hesíode, Treballs i dies 42–105, amb omissió de l’inventari de dons i dels qualificatius misògins. Es conserva el pla de Zeus, l’avís de Prometeu, l’acceptació d’Epimeteu, la gerra i l’esperança que queda dins. No es motiva l’obertura amb curiositat ni amb un encàrrec que el passatge no explicita. Distingir el mite de les causes reals de les malalties. Base M1.'),
      s('foc','Narrador','Hesíode, un poeta de l’antiga Grècia, explicava un mite sobre l’arribada dels mals al món. El relat comença amb una disputa entre Zeus, el rei dels déus, i Prometeu, que havia ajudat els humans. Zeus els havia amagat el foc. Prometeu el va recuperar d’amagat, dins d’una tija buida, i el va tornar a portar a la gent.'),
      s('pla','Narrador','Zeus es va enfadar quan va descobrir què havia fet Prometeu. Va preparar una altra resposta. Va ordenar que modelessin una dona de terra i aigua, i que els déus li donessin diversos dons. Aquella dona es deia Pandora. Zeus va decidir enviar-la a Epimeteu, el germà de Prometeu.'),
      s('avis','Narrador','Prometeu ja havia advertit el seu germà que retornés els regals que vinguessin de Zeus. Epimeteu va rebre Pandora i va acceptar el regal. El poema explica que només més tard va comprendre el que havia passat. A partir d’aquí, la història es concentra en una gerra gran, tapada, que guardava uns continguts extraordinaris.'),
      s('obertura','Narrador','Pandora va aixecar la tapa amb les mans. Del recipient van sortir els mals que fins aleshores havien quedat tancats. Es van escampar per la terra i pel mar. El relat hi inclou les malalties i les penes que fan difícil la vida de les persones. La gerra va quedar oberta mentre tot allò sortia i s’estenia pel món.'),
      s('tapa','Narrador','Quan Pandora va tornar a posar-hi la tapa, una cosa encara es trobava dins: l’esperança. Havia quedat sota la vora del recipient i no havia sortit amb la resta. La tapa es va tancar abans que pogués volar a fora. Així acaba l’escena de la gerra en aquesta versió del mite.'),
      s('mon','Narrador','Hesíode continua descrivint els mals que ja han sortit. Explica que es mouen entre la gent de dia i de nit i que les malalties arriben en silenci, perquè Zeus els ha tret la veu. Aquesta és la imatge que deixa el poema: els mals escampats pel món i l’esperança dins la gerra tancada. És una narració antiga sobre el patiment humà; avui l’escoltem com un mite transmès des d’una altra època.'),
      d('Cap efecte de monstres, ensurt, ales o tapa. No afegir una veu que absolgui o culpabilitzi Pandora, ni una sentència contra la curiositat. Mantenir el final ambigu de l’esperança, sense convertir-lo en una resposta moral.')],
    items:[
      q('foc','Què fa Prometeu amb el foc que Zeus ha amagat?','El recupera d’amagat i el porta als humans dins una tija buida.',['El tanca dins la gerra que després obrirà Pandora.','El recupera i el porta als humans dins una tija buida.','El retorna a Zeus perquè Epimeteu pugui rebre el regal.','El fa servir per fabricar la tapa de la gerra.'],'b','La primera acció explica per què Zeus prepara una resposta.',[e('foc','el va recuperar d’amagat, dins d’una tija buida, i el va tornar a portar a la gent')]),
      q('regal','Quina relació té Epimeteu amb Prometeu i què fa amb el regal?','És el seu germà i accepta el regal malgrat l’avís de retornar els de Zeus.',['És el seu ajudant i retorna Pandora a Zeus.','És el seu fill i amaga Pandora abans de l’avís.','És el seu germà i accepta el regal malgrat l’avís.','És el seu rival i impedeix que el regal arribi a casa.'],'c','El parentesc i l’avís s’han de relacionar amb la decisió d’Epimeteu.',[e('pla','Epimeteu, el germà de Prometeu'),e('avis','que retornés els regals que vinguessin de Zeus'),e('avis','va acceptar el regal')],2),
      q('escampa','Què s’escampa quan Pandora aixeca la tapa?','Els mals, incloses les malalties i les penes.',['Els dons que els déus encara no li havien donat.','El foc que Prometeu havia amagat als humans.','L’esperança, que surt abans que els mals.','Els mals, incloses les malalties i les penes.'],'d','El relat identifica els continguts que surten del recipient.',[e('obertura','Del recipient van sortir els mals'),e('obertura','les malalties i les penes')]),
      q('esperanca','Per què l’esperança no surt amb la resta?','Perquè queda dins i la tapa es tanca abans que pugui sortir.',['La tapa es tanca mentre l’esperança encara és dins.','Pandora la torna a atrapar després que hagi volat fora.','Epimeteu la rep de Prometeu dins la tija del foc.','Zeus l’amaga al mar abans que Pandora obri la gerra.'],'a','En aquesta versió, l’esperança no surt després ni és alliberada al final.',[e('tapa','La tapa es va tancar abans que pogués volar a fora')]),
      q('silenci','Com explica el poema que les malalties arribin en silenci?','Dient que Zeus els ha tret la veu.',['Dient que Pandora les guia perquè no facin soroll.','Dient que només es mouen quan ningú no dorm.','Dient que Zeus els ha tret la veu.','Dient que encara estan amagades sota la tapa.'],'c','Es pregunta per la imatge del mite, no per una causa científica.',[e('mon','les malalties arriben en silenci, perquè Zeus els ha tret la veu')]),
      q('seqüencia','Quin ordre d’accions correspon al relat?','Prometeu recupera el foc; Epimeteu accepta el regal; Pandora obre la gerra.',['Pandora obre la gerra; Prometeu recupera el foc; Zeus envia el regal.','Prometeu recupera el foc; Epimeteu accepta el regal; Pandora obre la gerra.','Zeus envia el regal; Pandora tanca la gerra; Epimeteu retorna Pandora.','Epimeteu retorna el regal; Prometeu amaga la gerra; Pandora recupera el foc.'],'b','La seqüència relaciona el conflicte inicial, l’arribada de Pandora i l’obertura.',[e('foc','el va recuperar d’amagat'),e('avis','va acceptar el regal'),e('obertura','Pandora va aixecar la tapa amb les mans')],2)
    ]}),
  cultural({code:'S154',id:'orfeu-i-euridice',title:'Orfeu i Eurídice',grade:'6',level:'advanced',universeIds:['mites-antiguitat'],voice:'Vindemiatrix',music:'M2',batch:'T-D',
    introduction:'Comprensió oral. Orfeu i Eurídice. Un episodi d’un mite grec.',
    summary:'Orfeu baixa al món dels morts per retrobar Eurídice. La possibilitat de tornar junts depèn d’una condició.',
    context:'Aquest mite parla de la pèrdua d’una persona estimada i d’un viatge al món dels morts. Escolta què demana Orfeu, quina resposta rep i què passa durant el camí de tornada.',
    editorialFocus:'6è avançada: espais simbòlics, condició temporal precisa, emoció que motiva una acció i resultat irreversible. Sis preguntes duals. Mort i dol sense detall gràfic. No convertir el desenllaç en una culpa moral ni afirmar que Orfeu gira perquè sent cap soroll afegit.',
    factualSources:[{label:'Ovidi, Metamorfosis X, 1–85, Orphée et Eurydice. Traducció històrica de G. T. Villenave (1806), Bibliotheca Classica Selecta, UCLouvain. Descens, cant, condició, mirada abans de sortir i segon intent denegat.',url:'https://bcs.fltr.ucl.ac.be/meta/10.htm'}],
    illustrationBrief:'Orfeu amb una lira a l’entrada d’un camí subterrani, llum suau a la roca. Sense Eurídice desapareixent, mirada enrere, governants del món dels morts o escena del desenllaç. Tractament respectuós i sense terror.',
    transcript:[d('Adaptació catalana pròpia d’Ovidi X, 1–85. S’ometen els presagis del casament, els noms i càstigs dels altres morts i la continuació posterior. La mort per serp s’esmenta sense detall. No s’inventa cap paraula d’Eurídice que desencadeni la mirada. El final queda en el retorn d’Orfeu després del segon pas denegat. Base M2, sense arpa o lira que pugui confondre’s amb un intèrpret real de l’escena.'),
      s('perdua','Narrador','Orfeu era un músic que cantava acompanyant-se amb una lira, un instrument de cordes. S’havia casat amb Eurídice. Poc després del casament, mentre ella caminava per l’herba, una serp la va mossegar i Eurídice va morir. Orfeu la va plorar durant molt de temps. Finalment, va decidir baixar al món dels morts per demanar que la deixessin tornar.'),
      s('cant','Narrador','Va entrar en aquell regne subterrani portant la lira. Va avançar entre les ombres fins al lloc on seien els dos déus que el governaven. Allà va començar a cantar. Amb la música i les paraules, els va explicar que havia perdut la seva esposa massa aviat. Els demanava que li retornessin la vida que encara li quedava per viure.'),
      s('condicio','Narrador','El seu cant va emocionar els qui l’escoltaven. Els governants van fer venir Eurídice i van permetre que seguís Orfeu cap a la sortida. Però li van posar una condició: ell havia de caminar al davant i no podia girar-se per mirar-la fins que haguessin sortit del món dels morts. Si es girava abans, Eurídice hi hauria de tornar.'),
      s('cami','Narrador','Van començar a pujar per un camí estret i fosc. Orfeu avançava primer. Eurídice el seguia al darrere. El trajecte s’enfilava i feia revolts; ell continuava caminant sense poder veure-la. A mesura que s’acostaven a la sortida, Orfeu tenia més por que ella no fos allà. Li faltava tan poc per tornar a trobar-la sota la llum!'),
      s('mirada','Narrador','Quan ja eren a prop de sortir, Orfeu es va girar. Va veure Eurídice, però encara no havien acabat el camí. Ella va començar a desaparèixer. Orfeu li va allargar els braços i va intentar abraçar-la; només va trobar aire. Eurídice va dir un adeu molt fluix i va tornar cap al món de les ombres.'),
      s('retorn','Narrador','Orfeu es va quedar immòbil. Després va provar de baixar de nou per recuperar-la, però aquesta vegada li van impedir el pas. Va esperar dies a la vora, suplicant una altra oportunitat. La resposta no va canviar. Al final va tornar tot sol al món dels vius. Així es tanca aquest episodi del mite: havia aconseguit que Eurídice el seguís, però l’havia mirada abans de travessar la sortida.'),
      d('Tensió continguda i silenci natural entre frases, sense efectes de por, crits o respiracions escenificades. No afegir cap consell final sobre confiança, paciència o obediència. Breu pujada musical respectuosa i fosa.')],
    items:[
      q('demanda','Què demana Orfeu als governants del món dels morts?','Que deixin tornar Eurídice a la vida per viure el temps que li quedava.',['Que el deixin quedar com a músic al seu regne.','Que li expliquin com havia mort Eurídice.','Que retornin a Eurídice la vida que li quedava.','Que li permetin veure-la sense tornar al món dels vius.'],'c','El cant presenta una petició de retorn, no només una visita.',[e('cant','Els demanava que li retornessin la vida que encara li quedava per viure')]),
      q('accepten','Què fa que els governants escoltin favorablement la petició?','El cant d’Orfeu els emociona.',['La promesa que Eurídice caminarà sense aturar-se.','El cant amb què Orfeu els explica la pèrdua.','L’amenaça d’Orfeu de quedar-se per sempre al camí.','El fet que Orfeu conegui tots els revolts de la sortida.'],'b','El relat connecta l’emoció provocada per la música amb el permís.',[e('condicio','El seu cant va emocionar els qui l’escoltaven')]),
      q('condicio','Fins quan ha d’esperar Orfeu per girar-se i mirar Eurídice?','Fins que tots dos hagin sortit del món dels morts.',['Fins que ell vegi la llum encara que ella sigui dins.','Fins que acabin de sentir la cançó a la sala dels déus.','Fins que Eurídice li demani que es giri al camí.','Fins que tots dos hagin sortit del món dels morts.'],'d','Veure la sortida o ser-hi a prop encara no compleix la condició.',[e('condicio','fins que haguessin sortit del món dels morts')]),
      q('por','Què el porta a girar-se quan ja són a prop de la sortida?','La por que Eurídice no sigui al seu darrere.',['La por que Eurídice no sigui al seu darrere.','La necessitat de tornar a buscar la lira que ha perdut.','Un crit amb què Eurídice li demana ajuda al revolt.','L’ordre dels governants perquè s’aturi a mirar el camí.'],'a','El relat situa la por creixent sense afegir un avís sonor.',[e('cami','tenia més por que ella no fos allà')]),
      q('fracassa','Per què Eurídice ha de tornar al món de les ombres?','Perquè Orfeu la mira quan encara no han acabat el camí.',['Perquè ella decideix caminar al davant d’Orfeu.','Perquè la música deixa de sonar abans d’arribar al revolt.','Perquè Orfeu la mira abans que tots dos hagin sortit.','Perquè els governants canvien la condició durant la pujada.'],'c','La mirada es produeix massa aviat respecte de la condició acceptada.',[e('mirada','Orfeu es va girar'),e('mirada','encara no havien acabat el camí'),e('condicio','Si es girava abans, Eurídice hi hauria de tornar')],2),
      q('nou','Què passa quan Orfeu intenta recuperar-la una altra vegada?','Li impedeixen tornar a baixar i, després d’esperar, se’n torna sol.',['Li permeten repetir el trajecte amb una condició diferent.','Li impedeixen el pas i al final torna sol al món dels vius.','Eurídice torna tota sola mentre ell espera a la vora.','Els governants li retornen la lira però es queden Eurídice.'],'b','L’episodi acaba després d’un segon intent sense accés al regne.',[e('retorn','aquesta vegada li van impedir el pas'),e('retorn','Al final va tornar tot sol al món dels vius')],2)
    ]}),
];
